import{_ as e,o as i,c as t,ag as r}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":null}'),o={name:"guide/introduction.md"};function l(n,a,d,c,s,p){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>Komari Next Pro 是为 Komari 编写的主题。3.0 使用独立的 React + TypeScript 实现，提供节点概览、网络历史、节点对比、全球节点和个性化外观。</p><h2 id="主题和-komari-的关系" tabindex="-1">主题和 Komari 的关系 <a class="header-anchor" href="#主题和-komari-的关系" aria-label="Permalink to &quot;主题和 Komari 的关系&quot;">​</a></h2><p>Komari 负责接收 Agent 上报、保存数据和提供 API；主题负责把这些信息展示出来。使用前需要已有可正常运行的 Komari 服务。</p><p>本项目的文档站仅用于介绍和使用说明，不会连接或展示你的生产节点。</p><h2 id="只装主题能用什么" tabindex="-1">只装主题能用什么 <a class="header-anchor" href="#只装主题能用什么" aria-label="Permalink to &quot;只装主题能用什么&quot;">​</a></h2><ul><li>节点概览、搜索、分组、卡片与紧凑布局。</li><li>服务器详情、资源历史、延迟和丢包曲线。</li><li>最多四台节点的基础信息与网络对比。</li><li>可旋转的全球节点地球。</li><li>资产、到期时间线、流量统计和世界时钟。</li><li>配色、透明度、本机背景及五种界面语言。</li></ul><p>服务器媒体库、链接下载和手动节点任务使用<a href="./extension">可选扩展服务</a>。</p><h2 id="数据边界" tabindex="-1">数据边界 <a class="header-anchor" href="#数据边界" aria-label="Permalink to &quot;数据边界&quot;">​</a></h2><p>IP 参考评分是可展开依据的规则估算，不代表真实信誉检测或风险概率。流媒体 HTTP 可达也不代表账号或地区已完整解锁。缺少历史或监测数据时，界面会保留未知，不把缺失数据填成零。</p>',10)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
